fn minmax(nums: Vec<i64>) -> (i64, i64) {
    let mut mn = nums[0].clone();
    let mut mx = nums[0].clone();
    for num in nums.iter().cloned() {
        if (num < mn) {
            mn = num
        }
        if (num > mx) {
            mx = num
        }
    }
    (mn, mx)
}

