async fn run_tasks() -> () {
    let f = tokio::spawn(async move { compute(7).await });
    let result = f.await.unwrap();
    println!("compute(7)={}", result);
    tokio::spawn(async move { log_bg("ping").await });
    let f1 = tokio::spawn(async move { fetch_add(10, 20).await });
    let f2 = tokio::spawn(async move { fetch_greet("world").await });
    println!("fetch_add={}, fetch_greet={}", f1.await.unwrap(), f2.await.unwrap());
    let label: Arc<String> = Arc::new("shared".to_string());
    let ft = tokio::spawn({ let label = Arc::clone(&label); async move { transform(&*label).await } });
    println!("label still: {}", label);
    println!("transform: {}", ft.await.unwrap());
    // let T'shared: read-only Arc<T>, task method receiver is Arc<Self>
    let w: Arc<Worker> = Arc::new(Worker { name: Arc::new("alice".to_string()), jobs: 5 });
    let fw = tokio::spawn({ let w = Arc::clone(&w); async move { w.run().await } });
    println!("w.name={}", w.name);
    fw.await.unwrap();
    // T'actor: Arc<Mutex<T>>, all accesses go through .lock().await
    let mut c: Arc<tokio::sync::Mutex<SharedCount>> = Arc::new(tokio::sync::Mutex::new(SharedCount::new()));
    c.lock().await.inc();
    c.lock().await.inc();
    println!("counter = {}", c.lock().await.value)
}

